{"packet_id":"D032-03","doc_id":"D032","jurisdiction":"Hoboken, NJ","category":"rent_increase_limits","lifecycle":"enacted","title":"Hoboken vacancy decontrol 25% initial rent cap","requirement":"Upon a registered apartment's vacancy, the new tenant's initial rent may not exceed 25% over the last rent (excluding any capital improvement surcharge), and decontrol requires a voluntary vacancy or legal eviction and may occur no more than once every three years.","key_value":"25% over prior rent","coverage_conditions":"Registered residential apartments in the city; on vacancy the unit is decontrolled for the new tenant's initial rental, with later increases still governed by the chapter.","applicability":{"conditions":[],"per_tenancy":"Decontrol applies upon vacancy of a registered unit; requires voluntary vacancy without harassment or a legal eviction; limited to once per three years.","coverage_quotes":[]},"exemptions":"The new tenant's initial rental is exempt from the chapter's rent controls; any further increase is not.","penalty":"The Board may rescind decontrol and revert the rent, and prosecute the landlord under § 155-21 (fine up to $2,000 per unit).","effective_date":null,"valid_through":null,"citation":"Hoboken Mun. Code § 155-31","quoted_span":"the apartment unit shall become decontrolled and exempt from the provisions of this chapter for the new tenant's initial rental; provided, however, that said rental shall be limited to an increase of 25% over the last rental paid by the tenant who voluntarily vacated the rental unit, exclusive of any capital improvement surcharge that is a component of said last rental","interaction":null,"relations":[],"confidence":0.9,"conflict_flag":false,"conflict_note":null}
{"packet_id":"D032-03","doc_id":"D032","jurisdiction":"Hoboken, NJ","category":"rent_increase_limits","lifecycle":"enacted","title":"Hoboken rent control baseline freeze","requirement":"A landlord may not charge rent above the level in effect on the chapter's effective date, nor above the rent received on January 11, 1973 where that exceeds the rent authorized by the chapter.","key_value":null,"coverage_conditions":"All rentals subject to Chapter 155; no building age, size or owner limits stated.","applicability":{"conditions":[],"per_tenancy":null,"coverage_quotes":[]},"exemptions":null,"penalty":"Chapter violations punishable under § 155-21, with a fine up to $2,000 per dwelling unit.","effective_date":null,"valid_through":null,"citation":"Hoboken Mun. Code § 155-25","quoted_span":"No landlord shall, after the effective date of this chapter, charge any rents in excess of what he was receiving from the effective date of this chapter; nor shall such landlord charge any rents in excess of what he was receiving on January 11, 1973, if such excess is in excess of the rental which is authorized by this chapter.","interaction":null,"relations":[],"confidence":0.9,"conflict_flag":false,"conflict_note":null}
